def _xor_encrypt_decrypt(data_bytes: bytes, key: str) -> bytes:
    key_bytes = key.encode('utf-8')
    key_len = len(key_bytes)
    return bytes(b ^ key_bytes[i % key_len] for i, b in enumerate(data_bytes))

def encrypt(text: str, key: str) -> str:
    """Encrypts text using XOR and Base64 encoding."""
    if not key:
        return text
    data_bytes = text.encode('utf-8')
    encrypted_bytes = _xor_encrypt_decrypt(data_bytes, key)
    return base64.b64encode(encrypted_bytes).d

